import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Сделать фотоколлаж — короткая работа: выберите несколько фото, выберите макет, расположите их и экспортируйте одно изображение. Это руководство проведёт вас по каждому шагу по порядку, от выбора фото до обмена готовым коллажем.</p>\n<p>Перед началом нужна всего одна вещь: фото, которые вы хотите объединить. От четырёх до девяти сильных фото с похожим светом дают лучший коллаж. Набор фото из одной поездки, одного события или одного ассортимента товаров работает лучше случайной смеси.</p>\n<p><a href=\"/ru/sozdat-fotokollazh/\">Создатель фотоколлажей</a> выполняет работу в вашем браузере. Ничего не загружается на сервер, учётная запись не нужна, а экспорт бесплатен. Следуйте шагам ниже — и через несколько минут у вас будет готовый коллаж.</p>\n<h2 id=\"step-1-choose-your-photos\">Шаг 1. Выберите фото</h2>\n<p>Выберите фото, которые принадлежат друг другу. Коллаж рассказывает маленькую историю, поэтому у фото должен быть общий сюжет: поездка, день рождения, ассортимент товаров или семейное собрание. Фото из одного события кажутся коллекцией; фото из пяти событий — случайной кучей.</p>\n<p>Выберите от четырёх до девяти фото. Четыре чисто заполняют сетку 2 на 2, а девять — сетку 3 на 3. Меньше четырёх оставляет пустые ячейки, а больше девяти делает каждое фото слишком маленьким, чтобы им наслаждаться. Качество побеждает количество в коллаже.</p>\n<p>Выбирайте фото с похожим светом и цветом. Набор, где одно фото тёмное и размытое, притягивает взгляд к слабому фото, а набор с последовательным светом выглядит как продуманная коллекция. Если одно фото намного темнее остальных, осветлите его перед началом или исключите.</p>\n<p>Выберите главное фото. Одно сильное изображение станет главным, увеличенным над остальными, поэтому выберите снимок, который лучше всего представляет набор. Главное фото обычно самое чёткое, яркое или эмоциональное в группе.</p>\n<h2 id=\"step-2-upload-the-photos\">Шаг 2. Загрузите фото</h2>\n<p>Откройте создатель коллажей и перетащите фото в зону загрузки или нажмите, чтобы выбрать их на устройстве. Можно загрузить их все сразу, и инструмент разместит их в сетке в том порядке, в котором вы их выбрали.</p>\n<p>Инструмент принимает файлы JPG, PNG, WebP, HEIC, GIF, BMP и SVG до 20 МБ каждый. Фото с телефона, скриншоты и графика — всё работает, а смесь форматов в одном коллаже допустима. HEIC-фото с iPhone загружается, как любой другой файл.</p>\n<p>Загрузка пяти и более фото автоматически выбирает сетку 3 на 3, а четырёх и менее — сетку 2 на 2. Если вы загрузите меньше фото, чем ячеек в сетке, пустые ячейки ждут новых фото, и вы можете добавить их позже.</p>\n<p>Если вы загрузили не то фото, удалите его, не начиная заново. Инструмент позволяет удалить одно фото из ячейки и заменить его, поэтому ошибка стоит секунд, а не перестройки всего коллажа.</p>\n<h2 id=\"step-3-pick-a-layout\">Шаг 3. Выберите макет</h2>\n<p>Выберите макет сетки или полосы. Сетка 2 на 2 подходит четырём фото, сетка 3 на 3 — девяти, вертикальная полоса — последовательности, читаемой сверху вниз, а горизонтальная полоса — последовательности, читаемой слева направо.</p>\n<p>Сетки подходят наборам, где каждое фото важно одинаково: поездке, событию или ассортименту товаров. Квадратная форма подходит лентам и карточкам, а равные ячейки дают каждому фото одинаковый вес.</p>\n<p>Полосы подходят последовательностям и сравнениям. Вертикальная полоса читается как история, что подходит дню по порядку. Горизонтальная полоса читается как шкала времени, что подходит сравнению «до и после» или панораме моментов.</p>\n<p>Свободно меняйте макет после загрузки. Фото остаются на месте, а ячейки перестраиваются, поэтому вы можете сравнить сетку и полосу за секунды. Макет, который лучше всего читается с первого взгляда, обычно правильный.</p>\n<h2 id=\"step-4-arrange-the-photos\">Шаг 4. Расположите фото</h2>\n<p>Перетащите фото на другую ячейку, чтобы поменять их местами на компьютере, или коснитесь для выбора и коснитесь ещё раз для обмена на телефоне. Обмен мгновенный, и вы можете переставлять столько раз, сколько хотите, перед экспортом.</p>\n<p>Поставьте главное фото в самую заметную ячейку. В сетке 2 на 2 это верхняя левая ячейка, которую глаз видит первой. В сетке 3 на 3 центр притягивает взгляд, поэтому главное принадлежит туда или в верхний левый угол.</p>\n<p>Сбалансируйте светлое и тёмное по сетке. Тёмное фото рядом с другим тёмным фото создаёт тяжёлый угол, а тёмное фото рядом со светлым балансирует коллаж. Распределяйте яркие и тёмные фото равномерно, а не группируйте их.</p>\n<p>Попробуйте несколько расположений, прежде чем решиться. Фото, которое выглядит потерянным в одной ячейке, может закрепить коллаж в другой, а обмен, занимающий секунду, может изменить весь баланс. Доверяйте расположению, которое лучше всего читается с первого взгляда.</p>\n<h2 id=\"step-5-feature-a-photo\">Шаг 5. Выделите фото</h2>\n<p>Сделайте главное фото больше остальных, настроив разрезы. Перетащите линию разреза, чтобы увеличить главную ячейку и уменьшить соседние, что даёт коллажу фокусную точку и иерархию вместо плоской сетки.</p>\n<p>Выбирайте главное и по качеству, и по сюжету. Главное должно быть самым резким, ярким фото набора, потому что увеличение слабого фото только привлекает внимание к его изъянам. Сильное фото, увеличенное, выглядит продуманно; слабое, увеличенное, — как ошибка.</p>\n<p>Держите главное фото одним. Два больших ячейки конкурируют друг с другом, и иерархия рушится, поэтому увеличьте одну ячейку явно над остальными, а остальные оставьте равными. Одно главное фото — правило, которое заставляет коллаж читаться с первого взгляда.</p>\n<p>Если разрезы стали неровными и вы хотите начать заново, верните их к равномерной сетке. Инструмент сбрасывает разрезы к равным ячейкам, поэтому вы можете попробовать другое главное расположение, не перестраивая коллаж.</p>\n<h2 id=\"step-6-adjust-gaps-and-corners\">Шаг 6. Настройте промежутки и углы</h2>\n<p>Задайте промежуток между ячейками. Нулевой промежуток делает бесшовный коллаж без границ, где фото касаются и образуют одно непрерывное изображение. Видимый промежуток разделяет фото на отдельные рамки, что подходит виду альбома или галереи.</p>\n<p>Задайте радиус углов для ячеек. Малый радиус смягчает коллаж и подходит постам в соцсетях, а квадратные углы кажутся формальными и подходят отпечаткам и карточкам. Большой радиус превращает каждую ячейку в скруглённую плитку, что подходит игривым дизайнам.</p>\n<p>Промежуток и радиус углов независимы, поэтому их можно свободно сочетать. Широкий промежуток с квадратными углами кажется галерейной стеной, а узкий промежуток со скруглёнными углами — приложением. Комбинация задаёт настроение коллажа.</p>\n<p>Цвет фона просвечивает сквозь промежутки, поэтому выбирайте промежуток и фон как пару. Белый промежуток на белом фоне выглядит как чистая граница, а фирменный цвет в промежутках связывает коллаж с кампанией.</p>\n<h2 id=\"step-7-set-the-background\">Шаг 7. Задайте фон</h2>\n<p>Выберите цвет фона из быстрых предустановок. Белый — значение по умолчанию и самый безопасный выбор: он сохраняет коллаж чистым, подходит любой ленте или странице и делает фото единственным цветом в изображении.</p>\n<p>Фирменный цвет превращает коллаж в продуманную графику. Цвет в промежутках связывает коллаж с кампанией, а набор коллажей в одном цвете образует узнаваемую серию. Используйте его, когда коллаж — такая же реклама, как и коллекция.</p>\n<p>Прозрачные PNG-стикеры, размещённые в ячейках, показывают цвет фона за собой. Стикер на белом фоне читается как чистый вырез, а стикер на цветном фоне получает оттенок от цвета за ним. Проверьте стикеры на фоне перед экспортом.</p>\n<p>Держите фон простым. Фон, который борется с фото, притягивает взгляд к промежуткам, а не к изображениям, а яркий цвет промежутка между приглушёнными фото делает коллаж пёстрым. Белый или мягкий нейтральный — безопасный выбор.</p>\n<h2 id=\"step-8-choose-the-canvas-size\">Шаг 8. Выберите размер холста</h2>\n<p>Выберите размер и соотношение холста под место назначения. Квадрат подходит лентам, карточкам и миниатюрам. Вертикаль подходит историям и обоям телефона. Широкий формат подходит баннерам и шапкам. Инструмент предлагает быстрые предустановки для каждой формы.</p>\n<p>Разрешение экспорта достигает 4000 пикселей, чего достаточно для печати. Выберите большой экспорт, когда коллаж может быть напечатан, и умеренный — когда он будет только опубликован онлайн. Позже всегда можно уменьшить, но нельзя добавить пиксели обратно.</p>\n<p>Проверьте предпросмотр при выбранном соотношении. Коллаж, который выглядит сбалансированным как квадрат, может показаться растянутым как вертикаль, потому что ячейки меняют форму. Поправьте расположение после смены соотношения, потому что лучший макет для одной формы может не подойти другой.</p>\n<p>Если не уверены, где будет использоваться коллаж, выберите квадрат. Это самая снисходительная форма: она предсказуемо обрезается везде и работает как миниатюра, изображение карточки и пост в ленте без дополнительных правок.</p>\n<h2 id=\"step-9-preview-the-collage\">Шаг 9. Проверьте коллаж</h2>\n<p>Посмотрите на полный предпросмотр перед экспортом. Проверьте, что каждое фото в правильной ячейке, главное фото заметно, промежутки ровные, а цвет фона выглядит так, как вы задумали. Предпросмотр в полном размере показывает детали, которые скрывает миниатюра.</p>\n<p>Проверьте каждую ячейку на плохую обрезку. Вписывание «Заполнить» может отрезать лицо, этикетку товара или строку текста на краю фото. Переключите вписывание на «Вместить» для любой ячейки, где обрезка вредит, и примите границу, которая с этим приходит.</p>\n<p>Посмотрите на коллаж на телефоне, если он предназначен для соцсетей. Цвет промежутка, который на мониторе компьютера выглядит нежным, на экране телефона может показаться громким, а коллаж, который при большом размере выглядит сбалансированным, при малом может показаться пёстрым. Телефон — это то место, где его увидит аудитория.</p>\n<p>Сравните коллаж и при малом размере тоже. Уменьшите вид до размера миниатюры и проверьте, читается ли коллаж по-прежнему. Коллаж, который работает только в полном размере, проваливается как пост в ленте, где его видят маленьким среди многих других.</p>\n<h2 id=\"step-10-export-and-share\">Шаг 10. Экспортируйте и поделитесь</h2>\n<p>Выберите формат экспорта. JPG подходит фотографиям и любому коллажу, где важен маленький файл, например посту в соцсети. PNG подходит коллажам с резким текстом, плоскими цветами или прозрачностью, которая должна пережить экспорт.</p>\n<p>Нажмите «Скачать» — и готовый коллаж сохранится на вашем устройстве. Имя файла отражает настройки коллажа, поэтому вы сможете различать версии, когда экспортируете несколько. Откройте файл и посмотрите на него ещё раз перед обменом.</p>\n<p>Поделитесь коллажем как одним изображением: загрузите его в ленту соцсети, прикрепите к сообщению или добавьте в карточку. Коллаж — это один файл, поэтому он публикуется, как любое другое изображение, а фото внутри него путешествуют вместе, куда бы ни пошёл файл.</p>\n<p>Храните исходные фото, а также готовый коллаж. Если позже понадобится другое соотношение, другой макет или исправленное фото, источники позволят перестроить за минуты. Плоский экспортированный коллаж нельзя легко отредактировать обратно в его части.</p>\n<h2 id=\"collages-for-print\">Коллажи для печати</h2>\n<p>Коллажу для печати нужен большой экспорт. Выберите максимальное разрешение, до 4000 пикселей, чтобы отпечаток оставался резким при нужном размере. Коллаж, экспортированный для соцсетей, плохо печатается при большом размере, потому что пикселей там нет.</p>\n<p>Выберите PNG для самого резкого отпечатка или высококачественный JPG для фотографического отпечатка. PNG сохраняет края и текст чёткими, а JPG эффективно сжимает фото. Оба работают при большом размере экспорта; выбор зависит от того, графический коллаж или фотографический.</p>\n<p>Проверьте соотношение сторон по размеру бумаги или рамки. Квадратный коллаж подходит квадратной рамке, а вертикальный коллаж — стандартному фотоотпечатку. Несовпадение означает обрезку отпечатка или жизнь с белыми полями, поэтому согласуйте соотношение перед экспортом.</p>\n<p>Сначала напечатайте маленький тест, когда коллаж важен, например подарок или отпечаток в рамке. Тестовый отпечаток выявляет сдвиги цвета и проблемы резкости, которые скрывает экран, и стоит намного меньше, чем повторная печать большой рамки.</p>\n<h2 id=\"fixing-a-collage-that-looks-off\">Как исправить коллаж, который выглядит не так</h2>\n<p>У коллажа, который выглядит не так, обычно одна из четырёх проблем: слабое фото, плохая обрезка, несбалансированное расположение или цвет промежутка, который борется с фото. Исправляйте их в этом порядке, начиная с самих фото.</p>\n<p>Сначала замените самое слабое фото. Тёмное, размытое или не по теме фото притягивает взгляд, где бы оно ни сидело, и никакое расположение не может его скрыть. Поменяйте его на более сильное фото из того же набора или перейдите к меньшей сетке без него.</p>\n<p>Затем проверьте обрезки. Лицо, отрезанное на краю ячейки, или объект, сжатый вписыванием, портит ячейку. Переключите вписывание на «Вместить» для этой ячейки или выберите для неё другое фото — и коллаж сразу улучшится.</p>\n<p>Затем сбалансируйте расположение. Разведите яркие фото, переместите главное в заметную ячейку и равномерно распределите тёмные фото. Один обмен часто исправляет коллаж, который казался неправильным без очевидной причины.</p>\n<p>Наконец, упростите промежутки и фон. Яркий цвет промежутка или пёстрый фон может сделать хороший коллаж шумным. Задайте промежутки белыми, а углы — с малым радиусом, и фото сами понесут коллаж.</p>\n<p>Если коллаж делается для детского праздника, яркие промежутки и скруглённые углы уместны: они добавляют игривости. Для делового отчёта или портфолио, наоборот, держите промежутки белыми, а углы квадратными.</p>\n<p>Для коллажа из скриншотов приложения используйте одинаковую ширину кадров. Скриншоты разной ширины в одной сетке дают рваные края, а одинаковая ширина делает коллаж аккуратным даже без дополнительных настроек.</p>\n<p>Проверьте коллаж в ленте рядом с другими постами. Коллаж, который отдельно выглядит спокойно, среди ярких постов может потеряться. Иногда чуть более смелый фон — это то, что нужно, чтобы выделиться.</p>\n<p>Делайте пробную печать на обычном принтере, прежде чем заказывать большой отпечаток. Проба покажет, как цвета ложатся на бумагу, и стоит копейки по сравнению с испорченным большим отпечатком.</p>\n<p>И последний совет: не бойтесь удалить фото из коллажа. Пустая ячейка иногда лучше слабого фото: четыре сильных снимка расскажут историю лучше, чем девять, из которых три — заполнители.</p>\n<h2 id=\"quick-reference\">Краткая справка: чек-лист коллажа</h2>\n<p>Выберите от четырёх до девяти сильных фото с похожим светом, загрузите их и выберите сетку или полосу. Расположите перетаскиванием или касанием для обмена, увеличьте главное фото и задайте промежутки, углы и фон.</p>\n<p>Выберите соотношение холста под место назначения, экспортируйте JPG для фото и PNG для графики и проверьте каждую ячейку на плохую обрезку в полном размере и в размере миниатюры. Храните исходные фото для перестройки позже.</p>\n<p>Полное руководство читайте в статье <a href=\"/ru/blog/sozdat-fotokollazh-polnoe-rukovodstvo/\">Как сделать фотоколлаж: полное руководство</a>, а идеи макетов — в статье <a href=\"/ru/blog/makety-kollazhej-setki-mudbordy-i-istorii/\">Макеты коллажей: сетки, мудборды и истории</a>. Соберите свой коллаж в <a href=\"/ru/sozdat-fotokollazh/\">создателе фотоколлажей</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Как выбрать, какие фото войдут в коллаж?","answer":"Выбирайте фото с общим сюжетом, например одна поездка, одно событие или один ассортимент товаров, и выберите от четырёх до девяти самых сильных. Фото с похожим светом и цветом выглядят как коллекция, а случайная смесь — как куча. Исключите любое фото, которое тёмное, размытое или не по теме."},{"question":"Что делать, если я загрузил меньше фото, чем ячеек в макете?","answer":"Пустые ячейки ждут новых фото, и вы можете добавить их позже. Можно также переключиться на меньший макет, например сетку 2 на 2 для четырёх фото, чтобы пустых ячеек не было. Не экспортируйте с пустыми ячейками, если пустое место не задумано."},{"question":"Можно ли переместить фото в другую ячейку?","answer":"Да. Перетащите фото на другую ячейку, чтобы поменять их местами на компьютере, или коснитесь для выбора и коснитесь ещё раз для обмена на телефоне или планшете. Переставлять можно столько раз, сколько хотите, перед экспортом, а предпросмотр обновляется мгновенно."},{"question":"Сохранять ли коллаж как JPG или PNG?","answer":"Используйте JPG для фотоколлажей и для любого изображения, где важен маленький файл, например для поста в соцсети. Используйте PNG для коллажей с резким текстом, плоскими цветами или прозрачностью, потому что PNG сохраняет каждый край чётким и сохраняет прозрачные области."},{"question":"Как напечатать мой коллаж?","answer":"Экспортируйте при самом большом разрешении, до 4000 пикселей, и согласуйте соотношение холста с размером бумаги или рамки. Выберите PNG для самого резкого отпечатка или высококачественный JPG для фотографического отпечатка и сначала сделайте маленький тестовый отпечаток для важной работы."},{"question":"Можно ли сделать коллаж на телефоне?","answer":"Да, создатель коллажей работает в браузере на телефонах и планшетах. Загрузите из фотобиблиотеки, касайтесь для обмена фото между ячейками и скачайте готовый коллаж. Обмен касанием заменяет перетаскивание на сенсорных экранах, поэтому расположение надёжно работает на мобильных устройствах."}];
